components.css:
.ds-law-book-scene { display: block; perspective: 900px; width: 155px; height: 225px; position: relative; margin: 0 auto; flex-shrink: 0; }
.ds-law-book-volume { --binding: #64292e; --binding-deep: #37181c; --binding-ink: #f0d59a; display: block; width: 143px; height: 218px; transform-style: preserve-3d; transform: rotateY(-18deg) rotateX(3deg); position: relative; transition: transform 420ms cubic-bezier(.16,1,.3,1); }
.ds-law-book-volume[data-color="forest"], .ds-book-color-option[data-color="forest"] { --binding: #244d3c; --binding-deep: #10271f; }
.ds-law-book-volume[data-color="navy"], .ds-book-color-option[data-color="navy"] { --binding: #263d55; --binding-deep: #132333; }
.ds-law-book-volume[data-color="cognac"], .ds-book-color-option[data-color="cognac"] { --binding: #805034; --binding-deep: #482f22; }
.ds-law-book-volume[data-color="ivory"], .ds-book-color-option[data-color="ivory"] { --binding: #e2d1ad; --binding-deep: #b3a07e; --binding-ink: #4e3924; }
.ds-law-book-volume[data-color="charcoal"], .ds-book-color-option[data-color="charcoal"] { --binding: #343a3c; --binding-deep: #1a2021; }
.ds-law-book-front { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; padding: 24px 16px 18px 21px; background-color: var(--binding); background-image: var(--leather-asset); background-size: 280px; background-blend-mode: soft-light; border-radius: 2px 5px 5px 2px; transform: translateZ(12px); box-shadow: inset 5px 0 6px rgba(0,0,0,.35), inset -2px 0 3px rgba(255,225,175,.14), 12px 12px 15px rgba(0,0,0,.28); color: var(--binding-ink); }
.ds-law-book-front::after { content: ""; position: absolute; inset: 12px 10px 12px 14px; border: 1px solid currentColor; opacity: .44; border-radius: 1px; pointer-events: none; }
.ds-law-book-frame { position: absolute; inset: 8px 6px 8px 10px; border: 1px solid currentColor; opacity: .45; border-radius: 2px; pointer-events: none; }
.ds-law-book-spine { width: 24px; position: absolute; top: 0; bottom: 0; left: 0; background: var(--binding-deep); transform: rotateY(-90deg) translateX(-12px); transform-origin: left; display: flex; align-items: center; justify-content: center; border-radius: 3px 0 0 3px; color: var(--binding-ink); border-block: 1px solid rgba(237,200,131,.2); }
.ds-law-book-spine > span { writing-mode: vertical-rl; max-height: 175px; overflow: hidden; font-family: var(--font-fraunces,Fraunces), Georgia, serif; font-size: .66rem; letter-spacing: .02em; white-space: nowrap; text-overflow: ellipsis; }
.ds-law-book-pages { position: absolute; width: 22px; top: 4px; bottom: 4px; right: 0; background: repeating-linear-gradient(90deg, #cfc0a1 0px, #f2e8d0 1px, #f2e8d0 3px); transform-origin: right; transform: rotateY(90deg) translateX(12px); border-radius: 0 2px 2px 0; }
.ds-law-book-author { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; font-size: .52rem; line-height: 1.5; text-align: center; max-width: 100%; margin-bottom: auto; opacity: .95; }
.ds-law-book-title { display: flex; flex-wrap: wrap; align-content: center; justify-content: center; column-gap: .22em; font-family: var(--font-fraunces,Fraunces), Georgia, serif; font-size: min(var(--cover-title-size, 1.17rem), 1.17rem); line-height: 1.14; text-align: center; overflow-wrap: normal; word-break: normal; hyphens: none; font-weight: 400; width: 100%; text-shadow: 0 1px 1px rgba(0,0,0,.45); }
.ds-law-book-title-word { display: inline-block; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-law-book-volume[data-title-density="compact"] .ds-law-book-title { font-size: min(calc(var(--cover-title-size) * .85), 1rem); }
.ds-law-book-volume[data-title-density="compact"] .ds-law-book-ornament { margin-block: 7px; }
.ds-law-book-volume[data-title-density="compact"] .ds-law-book-press { display: none; }
.ds-law-book-spine-title { display: none; }
.ds-law-book-ornament { display: flex; align-items: center; justify-content: center; gap: 5px; width: 75%; margin: 12px 0; }
.ds-law-book-ornament > span { height: 1px; flex: 1; background: currentColor; opacity: .65; }
.ds-law-book-imprint { text-align: center; font-size: .55rem; line-height: 1.3; margin-top: auto; }
.ds-law-book-press { margin-top: 9px; opacity: .8; }
.ds-law-book-volume[data-material="linen"] .ds-law-book-front { background-image: none; box-shadow: inset 3px 0 4px rgba(0,0,0,.2), 12px 12px 15px rgba(0,0,0,.25); }
.ds-law-book-volume[data-material="minimal"] .ds-law-book-front { background-image: none; }
.ds-law-book-volume[data-material="minimal"] .ds-law-book-frame, .ds-law-book-volume[data-material="minimal"] .ds-law-book-front::after, .ds-law-book-volume[data-material="minimal"] .ds-law-book-ornament { display: none; }
.ds-book-open-link:hover .ds-law-book-volume, .ds-book-open-link:focus-visible .ds-law-book-volume { transform: translateY(-7px) rotateY(-7deg) rotateX(0); }
.ds-volume-preview{color:var(--ink,#0c1c24);font-family:var(--font-sora,Sora),"Segoe UI",sans-serif;}.ds-book-open-link{display:flex;align-items:center;flex-direction:column;gap:1rem;color:inherit;text-decoration:none}.ds-book-open-link:focus-visible{outline:2px solid #f2d799;outline-offset:4px;border-radius:4px}.ds-volume-caption{font-size:.77rem;color:var(--ink-soft,#1a3340)}@media(prefers-reduced-motion:reduce){.ds-law-book-volume{transition:none}.ds-book-open-link:hover .ds-law-book-volume,.ds-book-open-link:focus-visible .ds-law-book-volume{transform:rotateY(-18deg) rotateX(3deg)}}
